// The chat page polls this several times a minute while a search runs, so the
// run's own row has to answer everything: no report tool, no agent, no model
// call, nothing that costs money or time.
const rows = $input.all().map((item) => item.json).filter((row) => row && row.runId);
const latest = rows[0] ?? null;
if (!latest) {
  return [{ json: { schemaVersion: 1, hasRun: false, running: false } }];
}
const minutesSince = (value) => {
  const parsed = Date.parse(String(value ?? ''));
  if (Number.isNaN(parsed)) return null;
  return Math.round((Date.now() - parsed) / 60000);
};
const running = String(latest.status ?? '') === 'running';
// While a run is open, errorSummary carries its progress heartbeat: the table
// gained no new column because setup cannot add one to a table that already
// exists, and the field is guaranteed empty until the run finishes and
// overwrites it with real errors.
let heartbeat = null;
if (running) {
  try {
    const parsed = JSON.parse(String(latest.errorSummary ?? ''));
    if (parsed && parsed.hb === 1) heartbeat = parsed;
  } catch {}
}
const startedMinutesAgo = minutesSince(latest.ranAt);
const quietMinutes = heartbeat ? minutesSince(heartbeat.at) : startedMinutesAgo;
// The same rule the report tool applies: silence decides death, not age. A
// beat can legitimately hold one API call for twenty-five minutes, so thirty
// quiet minutes is the first point at which "it stopped" is a fact. A row from
// before heartbeats existed only has its start time, so it gets the old rule.
const QUIET_AFTER = 30;
const DEAD_AFTER = 102;
const dead = running && (heartbeat
  ? quietMinutes !== null && quietMinutes >= QUIET_AFTER
  : startedMinutesAgo !== null && startedMinutesAgo >= DEAD_AFTER);
if (running && !dead) {
  return [{ json: {
    schemaVersion: 1,
    hasRun: true,
    running: true,
    startedAt: latest.ranAt,
    startedMinutesAgo,
    step: heartbeat ? Number(heartbeat.step) || 0 : 0,
    of: heartbeat ? Number(heartbeat.of) || 0 : 0,
    note: heartbeat ? String(heartbeat.note ?? '').slice(0, 200) : 'Getting started',
    updatedMinutesAgo: quietMinutes,
  } }];
}
return [{ json: {
  schemaVersion: 1,
  hasRun: true,
  running: false,
  interrupted: dead === true,
  status: dead ? 'interrupted' : String(latest.status ?? ''),
  finishedAt: dead ? null : latest.ranAt,
  newCount: Number(latest.newCount ?? 0) || 0,
  closingSoonCount: Number(latest.closingSoonCount ?? 0) || 0,
} }];
